grammar inference.fragments.TypedBasic hidden(WS)
generate fragments "urn:inference:fragments:typed_basic"
import "http://www.eclipse.org/emf/2002/Ecore" as ecore
Model: Fields;
fragment Fields: name=ID;
terminal ID: ('a'..'z')+;
terminal WS: (' '|'\t'|'\r'|'\n')+;

grammar inference.fragments.TypedExplicit hidden(WS)
generate fragments "urn:inference:fragments:typed_explicit"
import "http://www.eclipse.org/emf/2002/Ecore" as ecore
Model: Fields;
fragment Fields returns Base: name=ID;
terminal ID: ('a'..'z')+;
terminal WS: (' '|'\t'|'\r'|'\n')+;

grammar inference.fragments.TypedOptional hidden(WS)
generate fragments "urn:inference:fragments:typed_optional"
import "http://www.eclipse.org/emf/2002/Ecore" as ecore
Model: 'm' Fields?;
fragment Fields: name=ID;
terminal ID: ('a'..'z')+;
terminal WS: (' '|'\t'|'\r'|'\n')+;

grammar inference.fragments.TypedNested hidden(WS)
generate fragments "urn:inference:fragments:typed_nested"
import "http://www.eclipse.org/emf/2002/Ecore" as ecore
