terminal WS: (' '|'\t'|'\r'|'\n')+;

grammar inference.fragments.TypedMultipleCallers hidden(WS)
generate fragments "urn:inference:fragments:typed_multiple_callers"
import "http://www.eclipse.org/emf/2002/Ecore" as ecore
Model: things+=(A|B)*;
A: 'a' Fields;
B: 'b' Fields;
fragment Fields: name=ID;
terminal ID: ('a'..'z')+;
terminal WS: (' '|'\t'|'\r'|'\n')+;

