grammar inference.fragments.TypedEnum hidden(WS)
generate fragments "urn:inference:fragments:typed_enum"
import "http://www.eclipse.org/emf/2002/Ecore" as ecore
Model: Fields;
fragment Fields: mode=Mode;
enum Mode: A='a'|B='b';
terminal ID: ('a'..'z')+;
terminal WS: (' '|'\t'|'\r'|'\n')+;

grammar inference.fragments.TypedReferences hidden(WS)
generate fragments "urn:inference:fragments:typed_references"
import "http://www.eclipse.org/emf/2002/Ecore" as ecore
Model: things+=Item*;
Item: 'item' Fields;
fragment Fields: name=ID ('to' target=[Item])?;
terminal ID: ('a'..'z')+;
terminal WS: (' '|'\t'|'\r'|'\n')+;

grammar inference.fragments.TypedRecursive hidden(WS)
generate fragments "urn:inference:fragments:typed_recursive"
import "http://www.eclipse.org/emf/2002/Ecore" as ecore
